354|fn deleted_for_provision(expected: &IdentityRevision) -> bool {
355|    expected.revision > 1
356|        && expected.record.is_none()
357|        && expected.genesis.is_none()
358|        && expected.operation_id
359|            == format!(
360|                "delete-provision-{}-{}",
361|                expected.session_id,
362|                expected.revision - 1
363|            )
