373|async fn receipt(store: &IdentitySledStore, sid: &str) -> Result<Option<CleanProvisionReceipt>> {
374|    let cozo = store.cozo.clone();
375|    let sid = sid.to_owned();
376|    Ok(tokio::task::spawn_blocking(move || cozo.read_clean_provision(&sid)).await??)
