378|async fn native_proof(
379|    plan: &CleanPlan,
380|    strict_stopped: bool,
381|) -> Result<(storage::StorageGuard, IncusInstance)> {
382|    let native = IncusRootRepairBackend::local();
383|    let (instance, etag) = native.instance(CONTROL_PLANE_CHATBOT_CONTAINER).await?;
384|    if strict_stopped {
385|        ensure!(
386|            instance == plan.instance && etag == plan.instance_etag,
387|            "fresh native definition/ETag changed"
388|        );
389|        if plan.version == 2 {
390|            let (old, old_etag) = native
391|                .instance(
392|                    plan.previous_instance["name"]
393|                        .as_str()
394|                        .context("old native name absent")?,
395|                )
396|                .await?;
397|            ensure!(
398|                old == plan.previous_instance && old_etag == plan.previous_instance_etag,
399|                "retained old native definition/ETag changed"
400|            );
401|        }
402|    } else {
403|        ensure!(
404|            binding_matches(
405|                &serde_json::to_string(&parsed_native(&plan.instance)?)?,
406|                &serde_json::to_string(&parsed_native(&instance)?)?
407|            ),
408|            "clean native storage/UUID/config changed"
409|        );
410|    }
411|    let pool = native
412|        .pool(&plan.pool_name)
413|        .await?
414|        .context("native pool absent")?;
415|    ensure!(
416|        pool["driver"] == "dir"
417|            && pool["status"] == "Created"
418|            && pool["config"]["source"] == plan.pool_source,
419|        "native root pool changed"
420|    );
421|    let parsed = parsed_native(&instance)?;
422|    let plan = plan.clone();
423|    let guard = tokio::task::spawn_blocking(move || storage::verify(&plan)).await??;
424|    Ok((guard, parsed))
425|}
