432|pub(super) async fn guard_start(
433|    store: &IdentitySledStore,
434|    revision: &IdentityRevision,
435|    sled: &ContainerIdentitySled,
436|) -> Result<Option<CleanRootGuard>> {
437|    let Some(receipt) = receipt(store, &sled.session_id).await? else {
438|        return Ok(None);
439|    };
440|    let plan: CleanPlan = serde_json::from_str(&receipt.provenance_json)?;
441|    plan.validate()?;
442|    ensure!(
443|        revision.revision >= receipt.committed_revision
444|            && sled.wireguard_pubkey == plan.wireguard_pubkey
445|            && sled.btrfs_device.as_ref().is_some_and(|device| {
446|                let mut device = device.clone();
447|                device.attached = true;
448|                device == plan.binding
449|            })
450|            && sled.instance.as_ref().is_some_and(|i| binding_matches(
451|                &receipt.instance_json,
452|                &serde_json::to_string(i).unwrap_or_default()
453|            )),
454|        "clean receipt does not match authoritative binding"
455|    );
456|    let (guard, native) = native_proof(&plan, false).await?;
457|    let should_start = root_repair::decide_seeded_native_start(sled.active, &native.status)?;
458|    Ok(Some(CleanRootGuard {
459|        should_start,
460|        _storage: guard,
461|    }))
