472|        return Ok(None);
473|    };
474|    let snapshot = IncusRootRepairBackend::local()
475|        .default_project_state()
476|        .await?;
477|    let instance = snapshot
478|        .instances
479|        .iter()
480|        .find(|instance| instance.name == CONTROL_PLANE_CHATBOT_CONTAINER)
481|        .context("clean native power readback absent")?
482|        .clone();
483|    ensure!(
484|        instance.status == status && identity_instance_matches(sled, &instance),
485|        "clean native power readback differs"
486|    );
487|    crate::incus_observer::publish_repair_readback_locked(engine, &snapshot).await?;
488|    Ok(Some(instance))
