{"content":"1|//! Native Incus lifecycle observation and complete-root publication.
2|//!
3|//! The WebSocket is only a wakeup source. Every accepted lifecycle event is
4|//! followed by a strict full default-project readback; event payloads never
5|//! become plugin state.
6|
7|use crate::{
8|    method_contract_admission::admit_compiled_state_contract,
9|    mutation_engine::MutationEngine,
10|    sealed_schema_reader::{blob_catalog_dir_from_env, read_manifest_pinned_schema_document},
11|};
12|use anyhow::{Context, Result, ensure};
13|use op_plugins::state_plugins::incus::{
14|    IncusLifecycleObserver, IncusState, dispatch_incus_method_observed,
15|    subscribe_incus_default_project,
16|};
17|use std::{path::Path, sync::Arc};
18|
19|const PLUGIN: &str = "incus";
20|
21|pub(crate) struct PreparedIncusObservation {
22|    pub full_state: simd_json::OwnedValue,
23|    pub expected_schema_hash: String,
24|}
25|
26|
27|/// Host-side, read-only, metadata-only enrichment of disk device sources.
28|/// Bounded: existing absolute paths only; mode/size are not recorded, only
29|/// the identity token. Fails only on malformed paths, never on missing files.
30|fn attach_mount_identities(state: &mut op_plugins::state_plugins::incus::IncusState) -> Result<()> {
31|    use op_plugins::state_plugins::incus_device::{Device, NamedDevice};
32|    for instance in &mut state.instances {
33|        for field in [&mut instance.devices, &mut instance.expanded_devices] {
34|            for NamedDevice { device, .. } in field.iter_mut() {
35|                let Device::Disk(disk) = device else { continue };
36|                let Some(source) = disk.source.as_deref() else { continue };
37|                disk.source_identity = Some(mount_identity_token(source));
38|            }
39|        }
40|    }
41|    Ok(())
42|}
43|
44|/// `sha256("dev:ino")` truncated to 16 hex chars, or `"-"` when the source is
45|/// unstatable. Never returns raw numbers.
46|fn mount_identity_token(source: &str) -> String {
47|    use sha2::{Digest, Sha256};
48|    use std::os::unix::fs::MetadataExt;
49|    let metadata = || -> Option<std::fs::Metadata> {
50|        if source.len() > 4096
51|            || !source.starts_with('/')
52|            || source.chars().any(|c| c.is_control())
53|        {
54|            return None;
55|        }
56|        std::fs::metadata(source).ok()
57|    }();
58|    match metadata {
59|        Some(metadata) => {
60|            let token = format!("{}:{}", metadata.dev(), metadata.ino());
61|            let digest = Sha256::digest(token.as_bytes());
62|            format!("{digest:x}")[..16].to_string()
63|        }
64|        None => "-".to_string(),
65|    }
66|}
67|
68|fn compatible_seal(catalog: &Path) -> Result<()> {
69|    let pinned = read_manifest_pinned_schema_document(catalog, PLUGIN)?;
70|    admit_compiled_state_contract(&pinned, PLUGIN)
71|}
72|
73|fn prepare_observation(catalog: &Path, snapshot: &IncusState) -> Result<PreparedIncusObservation> {
74|    let pinned = read_manifest_pinned_schema_document(catalog, PLUGIN)?;
75|    admit_compiled_state_contract(&pinned, PLUGIN)?;
76|    let full_state = simd_json::serde::to_owned_value(snapshot)?;
77|    ensure!(
78|        pinned.schema.validate(&full_state).valid,
79|        "native Incus snapshot does not conform to the pinned plugin state schema"
80|    );
81|    pinned.schema.validate_public_state_policy()?;
82|    // Fail closed on an invalid policy or state/type drift. MutationEngine
83|    // repeats this exact pinned projection as the sole authority for audit and
84|    // live notification data while retaining the full private root in SHM.
85|    pinned.schema.project_public_state(&full_state)?;
86|    let after = read_manifest_pinned_schema_document(catalog, PLUGIN)?;
87|    ensure!(
88|        after.schema_hash == pinned.schema_hash
89|            && after.blob.schema_json == pinned.blob.schema_json,
90|        "Incus plugin seal changed during observation validation"
91|    );
92|    Ok(PreparedIncusObservation {
93|        full_state,
94|        expected_schema_hash: pinned.schema_hash,
95|    })
96|}
97|
98|async fn readback_and_publish(
99|    engine: &MutationEngine,
100|    observer: &IncusLifecycleObserver,
101|) -> Result<()> {
102|    // The same engine lock is held by the canonical Incus method dispatcher
103|    // from native effect through readback and commit. It prevents an older
104|    // observer read from overwriting a newer method observation.
105|    let _observation = engine.lock_host_observation().await;
106|    let mut snapshot = observer.default_project_state().await?;
107|    attach_mount_identities(&mut snapshot)?;
108|    let prepared = prepare_observation(&blob_catalog_dir_from_env(), &snapshot)?;
109|    engine
110|        .process_observed_state(PLUGIN, prepared.full_state, prepared.expected_schema_hash)
111|        .await
112|        .map_err(anyhow::Error::msg)?;
113|    Ok(())
114|}
115|
116|/// Called by identity root repair while it holds `lock_host_observation`
117|/// across the exact native effect and complete default-project readback.
118|/// Keep the same pinned seal and SHM publication path as ordinary Incus calls.
119|pub(crate) async fn publish_repair_readback_locked(
120|    engine: &MutationEngine,
121|    snapshot: &IncusState,
122|) -> Result<()> {
123|    let mut snapshot = snapshot.clone();
124|    attach_mount_identities(&mut snapshot)?;
125|    let prepared = prepare_observation(&blob_catalog_dir_from_env(), &snapshot)?;
126|    engine
127|        .process_observed_state(PLUGIN, prepared.full_state, prepared.expected_schema_hash)
128|        .await
129|        .map_err(anyhow::Error::msg)
130|        .map(|_| ())
131|}
132|
133|/// Subscribe first, then publish one initial complete snapshot. Each native
134|/// lifecycle wakeup produces another complete root replacement. Disconnect or
135|/// malformed data ends this task without deleting the last committed state;
136|/// only an explicit engine start/reload retries it.
137|pub(crate) async fn observe(engine: Arc<MutationEngine>) -> Result<()> {
138|    let catalog = blob_catalog_dir_from_env();
139|    compatible_seal(&catalog)?;
140|    let mut observer = subscribe_incus_default_project().await?;
141|    readback_and_publish(&engine, &observer)
142|        .await
143|        .context("initial Incus snapshot publication failed")?;
144|    loop {
145|        observer.wait_for_lifecycle().await?;
146|        readback_and_publish(&engine, &observer)
147|            .await
148|            .context("Incus lifecycle readback publication failed")?;
149|    }
150|}
151|
152|/// Canonical Incus method integration. The native method, immediate readback,
153|/// seal validation, and full/private plus projected/public commit share the
154|/// observer lock. A completed provider mutation is never reported as success
155|/// if its readback or publication fails.
156|pub(crate) async fn dispatch_method(
157|    engine: &MutationEngine,
158|    method: &str,
159|    args: &serde_json::Value,
160|) -> Result<serde_json::Value> {
161|    let engine = engine.clone();
162|    let method = method.to_string();
163|    let args = args.clone();
164|    tokio::spawn(async move { dispatch_method_owned(&engine, &method, &args).await })
165|        .await
166|        .context("Incus operation owner failed; reconciliation may be required")?
167|}
168|
169|async fn dispatch_method_owned(
170|    engine: &MutationEngine,
171|    method: &str,
172|    args: &serde_json::Value,
173|) -> Result<serde_json::Value> {
174|    // Repair takes the session lifecycle lock before the host observation
175|    // lock. Keep that order here, and retain both guards through readback.
176|    let target = match method {
177|        "add_device" | "update_device" | "remove_device" => args.get("instance_name"),
178|        "create_instance" | "modify_instance" | "delete_instance" | "start_instance"
179|        | "stop_instance" | "restart_instance" | "freeze_instance" | "unfreeze_instance"
180|        | "snapshot_instance" | "exec_instance" => args.get("name"),
181|        _ => None,
182|    };
183|    let _identity_target = if let Some(target) = target {
184|        let target = target.as_str().context("Incus target name is invalid")?;
185|        if uuid::Uuid::parse_str(target).is_ok_and(|uuid| uuid.to_string() == target) {
186|            Some(crate::identity_sled_dispatch::guard_identity_incus_target(engine, target).await?)
187|        } else {
188|            None
189|        }
190|    } else {
191|        None
