454|    let mut ids = HashSet::new();
455|    let mut sleds = Vec::new();
456|    for revision in &snapshot.identities {
457|        anyhow::ensure!(
458|            ids.insert(revision.session_id.as_str()),
459|            "duplicate identity revision"
460|        );
461|        let Some(record) = &revision.record else {
462|            continue;
463|        };
464|        anyhow::ensure!(
465|            record.session_id == revision.session_id,
466|            "revision row mismatch"
467|        );
468|        if let Some(genesis) = &revision.genesis {
469|            anyhow::ensure!(
470|                genesis.session_id == revision.session_id,
471|                "genesis row mismatch"
472|            );
473|        }
474|        sleds.push(record_to_sled(record, revision.genesis.as_ref())?);
475|    }
476|    sleds.sort_by(|left, right| left.session_id.cmp(&right.session_id));
477|    let events = snapshot
478|        .events
479|        .iter()
480|        .map(event_from_record)
481|        .collect::<anyhow::Result<Vec<_>>>()?;
482|    Ok(SledCacheState { sleds, events })
