119|/// Store ownership is injected once by MutationEngine startup. Opening failure is
120|/// returned by startup and can be retried by restarting startup; it is never cached
121|/// as `None` in a process-global OnceLock.
122|#[derive(Clone)]
123|pub(crate) struct IdentitySledStore {
124|    cozo: CozoGraphShuttle,
125|    lifecycle_locks:
126|        Arc<tokio::sync::Mutex<HashMap<String, std::sync::Weak<tokio::sync::Mutex<()>>>>>,
127|}
128|
129|impl IdentitySledStore {
130|    pub(crate) fn new(cozo: CozoGraphShuttle) -> Self {
131|        Self {
132|            cozo,
133|            lifecycle_locks: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
134|        }
135|    }
136|
137|    pub(crate) fn cozo(&self) -> &CozoGraphShuttle {
138|        &self.cozo
139|    }
140|
141|    async fn lifecycle_lock(&self, session_id: &str) -> Arc<tokio::sync::Mutex<()>> {
142|        let mut locks = self.lifecycle_locks.lock().await;
143|        locks.retain(|_, lock| lock.strong_count() != 0);
144|        if let Some(lock) = locks.get(session_id).and_then(std::sync::Weak::upgrade) {
145|            return lock;
146|        }
147|        let lock = Arc::new(tokio::sync::Mutex::new(()));
148|        locks.insert(session_id.to_string(), Arc::downgrade(&lock));
149|        lock
150|    }
