216|impl CozoGraphShuttle {
217|    /// Fail closed when domain owners share one database handle or when two
218|    /// persistent handles resolve to the same held root or data directory.
219|    pub fn ensure_distinct_from(&self, other: &Self) -> std::result::Result<(), CozoError> {
220|        if Arc::ptr_eq(&self.db, &other.db) {
221|            return Err(CozoError::Other(
222|                "Cozo domain owners must not share a database handle".into(),
223|            ));
224|        }
225|        match (&self.identity_directory, &other.identity_directory) {
226|            (Some(left), Some(right)) => left.ensure_distinct_from(right),
227|            _ => Ok(()),
228|        }
229|    }
