232|        let db = DbInstance::new("mem", "", Default::default()).map_err(|e| {
233|            CozoError::Other(format!("failed to create CozoDB in-memory instance: {e}"))
234|        })?;
235|        let s = Self {
236|            db: Arc::new(db),
237|            identity_directory: None,
238|            identity_transaction: Arc::new(std::sync::Mutex::new(())),
239|            runtime_document_transaction: Arc::new(std::sync::Mutex::new(())),
240|            episode_transaction: Arc::new(std::sync::Mutex::new(())),
241|            system_graph_transaction: Arc::new(std::sync::Mutex::new(())),
242|        };
243|        s.seed_schema().map_err(CozoError::from)?;
244|        Ok(s)
245|    }
246|
247|    pub fn new_persistent(path: PathBuf) -> std::result::Result<Self, CozoError> {
248|        Self::open_persistent(path, false)
249|    }
250|
251|    /// Open a credential-bearing store beneath service-only root/data
252|    /// directories. Restricts their held, nofollow-validated descriptors to
253|    ///0700 before Cozo can create/read its files; never changes process umask
254|    /// or generic store permissions. Custom options that could redirect data
255|    /// outside this private boundary are rejected before opening Cozo.
256|    pub fn new_persistent_private(path: PathBuf) -> std::result::Result<Self, CozoError> {
257|        Self::open_persistent(path, true)
