260|    fn open_persistent(path: PathBuf, private: bool) -> std::result::Result<Self, CozoError> {
261|        let ps = path
262|            .to_str()
263|            .ok_or_else(|| CozoError::Other("Cozo database path must be valid UTF-8".into()))?
264|            .to_string();
265|        let directory = if private {
266|            identity_transactions::PersistentIdentityBoundary::open_private(&path)?
267|        } else {
268|            identity_transactions::PersistentIdentityBoundary::open(&path)?
269|        };
270|        // RocksDB is the durable storage engine beneath CozoDB.
271|        let db = DbInstance::new("rocksdb", &ps, Default::default())
272|            .map_err(|e| CozoError::Other(format!("failed to open CozoDB at {ps}: {e}")))?;
273|        directory.verify()?;
274|        let s = Self {
275|            db: Arc::new(db),
276|            identity_directory: Some(Arc::new(directory)),
277|            identity_transaction: Arc::new(std::sync::Mutex::new(())),
278|            runtime_document_transaction: Arc::new(std::sync::Mutex::new(())),
279|            episode_transaction: Arc::new(std::sync::Mutex::new(())),
280|            system_graph_transaction: Arc::new(std::sync::Mutex::new(())),
281|        };
282|        s.seed_schema().map_err(CozoError::from)?;
283|        Ok(s)
284|    }
285|
286|    pub fn from_env() -> std::result::Result<Self, CozoError> {
287|        if let Ok(p) = std::env::var("COGNITIVE_COZO_DB_PATH") {
288|            Self::new_persistent(PathBuf::from(p))
289|        } else {
290|            Self::new_in_memory()
291|        }
292|    }
